reproduction.script:
import fs from 'node:fs';
import { buildClientSchema, buildSchema, getIntrospectionQuery, printSchema } from 'graphql';

const [endpoint, outputPath] = process.argv.slice(2);
if (!endpoint || !outputPath) throw new Error('Usage: node introspect.mjs <endpoint> <output.graphql>');

const query = getIntrospectionQuery({
  descriptions: true,
  specifiedByUrl: false,
  directiveIsRepeatable: false,
  schemaDescription: false,
  inputValueDeprecation: false,
});

const response = await fetch(endpoint, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ query }),
});
if (!response.ok) throw new Error(`HTTP ${response.status} ${response.statusText}`);

const payload = await response.json();
if (payload.errors?.length) throw new Error(JSON.stringify(payload.errors));
if (!payload.data?.__schema) throw new Error('Missing __schema');

const clientSchema = buildClientSchema(payload.data);
const sdl = `${printSchema(clientSchema)}\n`;
buildSchema(sdl);
fs.writeFileSync(outputPath, sdl, 'utf8');
console.log(`WROTE=${outputPath} BYTES=${Buffer.byteLength(sdl, 'utf8')}`);
